import { apiRequest, supabaseClient } from "./api.js";

const palettes=[["#32143f","#c66a9d"],["#0f3a48","#d7a53d"],["#54202a","#e48a55"],["#162f25","#87a94a"],["#2a245a","#7d6ed1"],["#5b2f17","#c99250"]];
let books=[];
let genres=[];
let metrics={books_submitted:0,authors_registered:0,pending:0,in_review:0,needs_info:0,approved:0,denied:0,published:0};
let currentUser=null;
let route="dashboard", selectedBook=null, arrangeGenre="", arrangeDrafts=new Map(), filters={search:"",status:"All",genre:"All"};
let pendingCoverUpload=null;
let publishNotice='',catalogDraft=null;
const audit=[];
const login=document.querySelector('#login'),app=document.querySelector('#app'),view=document.querySelector('#view'),modalRoot=document.querySelector('#modalRoot');

document.querySelector('#loginForm').addEventListener('submit',async e=>{
  e.preventDefault();
  const button=document.querySelector('#loginButton'), error=document.querySelector('#loginError');
  error.hidden=true;button.disabled=true;button.textContent='Signing in…';
  try{
    const email=document.querySelector('#loginEmail').value.trim();
    const password=document.querySelector('#loginPassword').value;
    const {error:signInError}=await supabaseClient.auth.signInWithPassword({email,password});
    if(signInError)throw signInError;
    await loadLiveData();
    login.hidden=true;app.hidden=false;render();
  }catch(err){error.textContent=err.message||'Sign in failed.';error.hidden=false;await supabaseClient.auth.signOut();}
  finally{button.disabled=false;button.textContent='Sign in to Review Hub';}
});
document.querySelector('#logout').onclick=async()=>{await supabaseClient.auth.signOut();app.hidden=true;login.hidden=false;books=[];currentUser=null};
document.querySelector('#quickReview').onclick=()=>openBook(books.find(b=>b.status==='Pending'));
document.querySelector('#menuBtn').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');

function mapBook(row,index){return {id:row.book_id,submission:row.submission_id,title:row.book_title,author:row.author_name,email:row.author_email,genre:row.genre,status:row.review_status||'Pending',reviewer:row.assigned_reviewer_email||'Unassigned',date:formatDate(row.submitted_at),destination:row.destination_type||'Other',url:row.submitted_destination_url||'',notes:row.reviewer_notes||'',pin:String(row.is_pinned).toLowerCase()==='true',order:Number(row.display_order||0),palette:palettes[index%palettes.length],published:row.publication_status==='Published',publicationStatus:row.publication_status||'Not Published',coverFileId:row.drive_cover_file_id||'',coverReference:row.drive_cover_reference||'',sourceType:row.source_type,squarespaceCoverUrl:row.squarespace_cover_url||'',publishedPageKey:row.published_page_key||'',recordVersion:Number(row.record_version||1),possibleDuplicate:String(row.possible_duplicate).toLowerCase()==='true',duplicateReason:row.duplicate_reason||'',availabilityAgreement:row.availability_agreement||'',promotionAgreement:row.promotion_agreement||''};}
function formatDate(value){if(!value)return '';const date=new Date(value);return Number.isNaN(date.getTime())?String(value):date.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});}
async function loadLiveData(){const data=await apiRequest('bootstrap');currentUser=data.user;metrics=data.metrics;genres=(data.genres||[]).map(g=>g.display_name||g.form_value);books=(data.books||[]).map(mapBook);const initials=(currentUser.display_name||currentUser.email).split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();document.querySelector('#profileAvatar').textContent=initials;document.querySelector('#profileName').textContent=currentUser.display_name||currentUser.email;document.querySelector('#profileRole').textContent=currentUser.role;}

(async()=>{const {data:{session}}=await supabaseClient.auth.getSession();if(!session)return;try{await loadLiveData();login.hidden=true;app.hidden=false;render();}catch(err){await supabaseClient.auth.signOut();}})();

function renderNav(){const navItems=[['dashboard','▦','Dashboard',''],['queue','≡','Review Queue',metrics.pending],['approved','✓','Approved',metrics.approved],['needs','?','Needs Info',metrics.needs_info],['denied','×','Denied',metrics.denied],['arrange','⌘','Arrange Catalog',''],['publish','↑','Publish',''],['audit','◷','Audit Log',''],['admin','⚙','Admin / Settings','']];document.querySelector('#nav').innerHTML=navItems.map(([id,icon,label,badge])=>`<button class="nav-btn ${route===id?'active':''}" data-route="${id}"><span>${icon}&nbsp;&nbsp; ${label}</span>${badge!==''?`<span class="badge">${badge}</span>`:''}</button>`).join('');document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{route=b.dataset.route;selectedBook=null;document.querySelector('.sidebar').classList.remove('open');render();});}
function render(){renderNav();view.className='view';if(selectedBook){renderReview();setTimeout(hydrateCovers,0);return;}({dashboard:renderDashboard,queue:()=>renderQueue(),approved:()=>renderQueue('Approved'),needs:()=>renderQueue('Needs Info'),denied:()=>renderQueue('Denied'),arrange:renderArrange,publish:renderPublish,audit:renderAudit,admin:renderAdmin}[route]||renderDashboard)();view.focus();setTimeout(hydrateCovers,0);}
function metric(label,value,note){return `<article class="metric"><div class="label"><span>${label}</span><span>•</span></div><strong>${value}</strong><small class="${note?.startsWith('+')?'delta':''}">${note||'BRAE 2026'}</small></article>`}
function renderDashboard(){const reviewed=metrics.approved+metrics.denied+metrics.needs_info;const pct=metrics.books_submitted?Math.round(reviewed/metrics.books_submitted*100):0;const name=(currentUser?.display_name||currentUser?.email||'BRAE Admin').split(' ')[0];view.innerHTML=`<div class="page-head"><div><p class="eyebrow">BRAE 2026</p><h1>Welcome, ${name}.</h1><p>Here’s where the current review cycle stands.</p></div><button class="secondary" onclick="window.print()">Export summary</button></div><section class="metrics">${metric('Authors registered',metrics.authors_registered)}${metric('Books submitted',metrics.books_submitted)}${metric('Pending',metrics.pending)}${metric('In review',metrics.in_review)}${metric('Needs info',metrics.needs_info)}${metric('Approved',metrics.approved)}${metric('Denied',metrics.denied)}${metric('Published',metrics.published)}</section><section class="dashboard-grid"><div><article class="panel"><div class="panel-head"><div><p class="eyebrow">REVIEW PROGRESS</p><h2>${reviewed} of ${metrics.books_submitted} books decided</h2></div><span class="progress-big">${pct}%</span></div><div class="progress-line"><span style="width:${pct}%"></span></div><small class="muted">${metrics.pending+metrics.in_review} books remain in the active review queue</small></article></div><article class="panel"><div class="panel-head"><h2>Live data connected</h2></div><p class="muted">Dashboard totals and submissions are being read from the BRAE Google workbook.</p><button class="primary wide" data-next style="margin-top:18px" ${metrics.pending?'':'disabled'}>Review next pending book</button></article></section>`;bindGo();}
const coverCache=new Map();
function cover(b,large=false){const format=b.sourceType==='AUDIOBOOK'?'<b class="format-badge audio">Audiobook</b>':'<b class="format-badge ebook">Ebook</b>';return b.coverFileId?`<div class="cover ${large?'cover-lg':''}" style="background:linear-gradient(145deg,${b.palette[0]},${b.palette[1]})">${format}<img data-cover-id="${b.coverFileId}" data-cover-title="${escapeHtml(b.title)}" alt="" loading="lazy"><span>${escapeHtml(b.title)}</span></div>`:`<div class="cover ${large?'cover-lg':''}" style="background:linear-gradient(145deg,${b.palette[0]},${b.palette[1]})" role="img" aria-label="Cover unavailable for ${escapeHtml(b.title)}">${format}<span>${escapeHtml(b.title)}</span></div>`}
let coverErrorShown=false;
async function hydrateCovers(){const images=[...document.querySelectorAll('img[data-cover-id]')];await Promise.all(images.map(async img=>{const id=img.dataset.coverId;try{if(!coverCache.has(id)){const result=await apiRequest('getCover',{fileId:id});coverCache.set(id,result.dataUrl);}img.src=coverCache.get(id);img.alt=`Cover of ${img.dataset.coverTitle}`;img.nextElementSibling?.remove();}catch(err){img.remove();if(!coverErrorShown){coverErrorShown=true;const notice=document.createElement('div');notice.className='warning cover-api-error';notice.textContent=`Cover preview error: ${err.message||'Unknown error'}`;view.prepend(notice);}}}));}
function escapeHtml(value){return String(value||'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));}
function statusClass(s){return s.toLowerCase().replaceAll(' ','')}
function renderQueue(forced){if(forced)filters.status=forced;const list=books.filter(b=>(filters.status==='All'||b.status===filters.status)&&(filters.genre==='All'||b.genre===filters.genre)&&(`${b.title} ${b.author} ${b.email} ${b.id}`.toLowerCase().includes(filters.search.toLowerCase())));const title=forced||'Review Queue';view.innerHTML=`<div class="page-head"><div><p class="eyebrow">BOOK SUBMISSIONS</p><h1>${title}</h1><p>${list.length} live record${list.length===1?'':'s'} shown</p></div><button class="primary" data-next ${books.some(b=>b.status==='Pending')?'':'disabled'}>Claim next unassigned</button></div><div class="toolbar"><input id="search" class="field search" placeholder="Search author, title, email or ID" value="${escapeHtml(filters.search)}"/><select id="statusFilter" class="field"><option>All</option>${['Pending','In Review','Needs Info','Approved','Denied'].map(x=>`<option ${filters.status===x?'selected':''}>${x}</option>`).join('')}</select><select id="genreFilter" class="field"><option>All</option>${genres.map(x=>`<option ${filters.genre===x?'selected':''}>${escapeHtml(x)}</option>`).join('')}</select><select class="field"><option>Oldest submitted</option><option>Newest submitted</option><option>Author A–Z</option><option>Title A–Z</option></select></div><div class="table-wrap">${list.length?`<table class="table"><thead><tr><th><input type="checkbox" aria-label="Select all"></th><th>Book</th><th>Author</th><th>Genre</th><th>Submitted</th><th>Status</th><th>Reviewer</th><th></th></tr></thead><tbody>${list.map(b=>`<tr><td><input type="checkbox" aria-label="Select ${escapeHtml(b.title)}"></td><td><div style="display:flex;gap:11px;align-items:center">${cover(b)}<div><button class="book-link" data-book="${b.id}">${escapeHtml(b.title)}</button><small class="muted" style="display:block">${b.id}</small></div></div></td><td>${escapeHtml(b.author)}</td><td>${escapeHtml(b.genre)}</td><td>${b.date}</td><td><span class="status ${statusClass(b.status)}">${b.status}</span></td><td>${escapeHtml(b.reviewer)}</td><td><button class="icon-btn" data-book="${b.id}" aria-label="Review ${escapeHtml(b.title)}">→</button></td></tr>`).join('')}</tbody></table><div class="pagination"><span>Showing ${list.length} of ${books.length} submissions</span></div>`:`<div class="empty"><h2>No submissions found</h2><p>Clear a filter or try a different search.</p></div>`}</div>`;document.querySelector('#search').oninput=e=>{filters.search=e.target.value;renderQueue(forced)};document.querySelector('#statusFilter').onchange=e=>{filters.status=e.target.value;renderQueue()};document.querySelector('#genreFilter').onchange=e=>{filters.genre=e.target.value;renderQueue(forced)};document.querySelectorAll('[data-book]').forEach(x=>x.onclick=()=>openBook(books.find(b=>b.id===x.dataset.book)));bindGo();}
function openBook(book){selectedBook=book;route='queue';render();}
function renderReview(){const b=selectedBook;if(!b){renderQueue();return;}pendingCoverUpload=null;view.innerHTML=`<div class="page-head"><div><button class="link-btn" id="backQueue">← Back to queue</button><p class="eyebrow" style="margin-top:14px">${b.id}</p><h1>${escapeHtml(b.title)}</h1><p>Submitted by ${escapeHtml(b.author)} on ${b.date}</p></div><div><button class="secondary" id="prevBook">← Previous</button> <button class="secondary" id="nextBook">Next →</button></div></div><section class="review-layout"><article class="panel cover-panel">${cover(b,true)}<small id="coverStatus">Google Drive review copy</small>${b.possibleDuplicate?`<div class="warning">⚠ POSSIBLE DUPLICATE<br><small>${escapeHtml(b.duplicateReason)}</small></div>`:''}</article><article class="panel"><div class="panel-head"><h2>Submission details</h2><span class="status ${statusClass(b.status)}">${b.status}</span></div><div class="form-grid"><label>Book title<input class="field" id="editTitle" value="${escapeHtml(b.title)}"></label><label>Author name<input class="field" id="editAuthor" value="${escapeHtml(b.author)}"></label><label>Author email<input class="field" id="editEmail" type="email" value="${escapeHtml(b.email)}"></label><label>Genre<select class="field" id="editGenre">${genres.map(g=>`<option ${g===b.genre?'selected':''}>${escapeHtml(g)}</option>`).join('')}</select></label><label>Format / event<select class="field" id="editSourceType"><option value="ONE_DAY_EBOOK" ${b.sourceType==='ONE_DAY_EBOOK'?'selected':''}>1-Day Ebook</option><option value="FULL_EVENT_EBOOK" ${b.sourceType==='FULL_EVENT_EBOOK'?'selected':''}>Full Event Ebook</option><option value="AUDIOBOOK" ${b.sourceType==='AUDIOBOOK'?'selected':''}>Audiobook</option></select></label><label>Upload new cover<input class="field" id="editCoverUpload" type="file" accept="image/jpeg,image/png,image/webp"><small class="muted">JPG, PNG or WebP. Maximum 5 MB.</small></label><label>Destination type<select class="field" id="editDestination"><option>${escapeHtml(b.destination)}</option><option>Amazon</option><option>BookFunnel</option><option>Books2Read</option><option>Other</option></select></label><label>Destination URL<input class="field" id="editUrl" value="${escapeHtml(b.url)}"></label><label class="full">Reviewer notes<textarea class="field" id="editNotes" rows="5" placeholder="Internal notes are never published">${escapeHtml(b.notes)}</textarea></label></div>${b.url?`<div class="warning">Verify the submitted destination before approval. <a href="${escapeHtml(b.url)}" target="_blank" rel="noopener">Open link ↗</a></div>`:''}</article><aside class="panel review-actions"><div class="panel-head"><h2>Decision</h2></div><div class="action-stack"><button class="primary" data-decision="Approved">✓ Approve</button><button class="secondary" data-modal="needs">? Needs Info</button><button class="danger" data-modal="deny">× Deny</button><button class="secondary" data-save>Save without decision</button></div><ul class="meta-list"><li><span>Assigned to</span><strong>${escapeHtml(b.reviewer)}</strong></li><li><span>Submission ID</span><strong>${b.submission}</strong></li><li><span>Format</span><strong>${b.sourceType==='AUDIOBOOK'?'Audiobook':'Ebook'}</strong></li><li><span>Availability agreed</span><strong>${escapeHtml(b.availabilityAgreement)}</strong></li></ul></aside></section>`;document.querySelector('#backQueue').onclick=()=>{selectedBook=null;render()};document.querySelector('#prevBook').onclick=()=>moveBook(-1);document.querySelector('#nextBook').onclick=()=>moveBook(1);document.querySelector('#editCoverUpload').onchange=prepareCoverUpload;document.querySelector('[data-decision]').onclick=()=>decision('Approved');document.querySelector('[data-modal="needs"]').onclick=()=>decisionModal('Needs Info');document.querySelector('[data-modal="deny"]').onclick=()=>decisionModal('Denied');document.querySelector('[data-save]').onclick=saveCurrentBook;}
async function prepareCoverUpload(event){const file=event.target.files[0];pendingCoverUpload=null;if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){event.target.value='';toast('Choose a JPG, PNG or WebP cover');return}if(file.size>5*1024*1024){event.target.value='';toast('The cover must be 5 MB or smaller');return}const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('The cover could not be read.'));reader.readAsDataURL(file)});pendingCoverUpload={name:file.name,mimeType:file.type,dataUrl};const panel=document.querySelector('.cover-panel .cover');if(panel){panel.innerHTML=`<b class="format-badge ${selectedBook.sourceType==='AUDIOBOOK'?'audio':'ebook'}">${selectedBook.sourceType==='AUDIOBOOK'?'Audiobook':'Ebook'}</b><img src="${dataUrl}" alt="New cover preview for ${escapeHtml(selectedBook.title)}">`}document.querySelector('#coverStatus').textContent=`New cover selected: ${file.name}`}
async function saveCurrentBook(){const b=selectedBook;const button=document.querySelector('[data-save]');button.disabled=true;button.textContent=pendingCoverUpload?'Uploading cover…':'Saving…';try{const result=await apiRequest('saveBook',{bookId:b.id,recordVersion:b.recordVersion,coverUpload:pendingCoverUpload,changes:{book_title:document.querySelector('#editTitle').value,author_name:document.querySelector('#editAuthor').value,author_email:document.querySelector('#editEmail').value,genre:document.querySelector('#editGenre').value,source_type:document.querySelector('#editSourceType').value,destination_type:document.querySelector('#editDestination').value,submitted_destination_url:document.querySelector('#editUrl').value,reviewer_notes:document.querySelector('#editNotes').value}});const updated=mapBook(result.book,books.indexOf(b));books[books.indexOf(b)]=updated;selectedBook=updated;pendingCoverUpload=null;toast('Changes saved to Google Sheets');render();}catch(err){toast(err.message||'Changes were not saved.');button.disabled=false;button.textContent='Save without decision';}}
function moveBook(dir){const i=books.indexOf(selectedBook);selectedBook=books[(i+dir+books.length)%books.length];render()}
async function decision(status,reason='',notes=''){const target=selectedBook;try{const result=await apiRequest('decideBook',{bookId:target.id,status,reason,notes,recordVersion:target.recordVersion});const updated=mapBook(result.book,books.indexOf(target));books[books.indexOf(target)]=updated;metrics.pending=books.filter(b=>b.status==='Pending').length;metrics.in_review=books.filter(b=>b.status==='In Review').length;metrics.needs_info=books.filter(b=>b.status==='Needs Info').length;metrics.approved=books.filter(b=>b.status==='Approved').length;metrics.denied=books.filter(b=>b.status==='Denied').length;toast(`${target.title} marked ${status}`);const i=books.indexOf(updated);selectedBook=books.slice(i+1).find(b=>b.status==='Pending')||books.find(b=>b.status==='Pending')||null;render();}catch(err){toast(err.message||'Decision was not saved.');}}
function arrangeGroups(){const approved=books.filter(b=>b.status==='Approved'),groups=[];if(approved.some(b=>b.sourceType==='AUDIOBOOK'))groups.push({key:'AUDIOBOOK',label:'Audiobooks · All genres'});if(approved.some(b=>b.sourceType==='ONE_DAY_EBOOK'))groups.push({key:'ONE_DAY_EBOOK',label:'One-Day Ebooks · All genres'});[...new Set(approved.filter(b=>b.sourceType==='FULL_EVENT_EBOOK').map(b=>b.genre).filter(Boolean))].sort((a,b)=>a.localeCompare(b)).forEach(genre=>groups.push({key:`FULL_EVENT_EBOOK||${genre}`,label:`Full-Event Ebooks · ${genre}`}));return groups}function orderedGenreBooks(groupKey){const [sourceType,genre]=String(groupKey||'').split('||');return books.filter(b=>b.status==='Approved'&&b.sourceType===sourceType&&(!genre||b.genre===genre)).sort((a,b)=>(a.order||Number.MAX_SAFE_INTEGER)-(b.order||Number.MAX_SAFE_INTEGER)||a.title.localeCompare(b.title))}
function draftGenreBooks(groupKey){const base=orderedGenreBooks(groupKey);if(!arrangeDrafts.has(groupKey))arrangeDrafts.set(groupKey,base.map(b=>b.id));const ids=arrangeDrafts.get(groupKey),byId=new Map(base.map(b=>[b.id,b])),draft=ids.map(id=>byId.get(id)).filter(Boolean);base.forEach(b=>{if(!ids.includes(b.id))draft.push(b)});return draft}
function renderArrange(){const approved=books.filter(b=>b.status==='Approved'),groups=arrangeGroups(),groupKeys=groups.map(group=>group.key);if(!groupKeys.includes(arrangeGenre))arrangeGenre=groupKeys[0]||'';const list=draftGenreBooks(arrangeGenre),currentGroup=groups.find(group=>group.key===arrangeGenre);view.innerHTML=`<div class="page-head"><div><p class="eyebrow">PUBLIC PAGE ORDER</p><h1>Arrange Catalog</h1><p>Arrange Audiobooks and One-Day Ebooks as mixed-genre pages. Full-Event Ebooks are arranged on separate genre pages.</p></div><div class="page-actions"><button class="secondary" id="saveOrder" ${list.length?'':'disabled'}>Save this page</button><button class="primary" id="saveAllOrder" ${approved.length?'':'disabled'}>Save all pages</button></div></div><div class="toolbar arrange-head"><select class="field" id="arrangeGenre" ${groups.length?'':'disabled'}>${groups.length?groups.map(group=>`<option value="${escapeHtml(group.key)}" ${group.key===arrangeGenre?'selected':''}>${escapeHtml(group.label)}</option>`).join(''):'<option>No approved catalog pages</option>'}</select><strong>${list.length} APPROVED ${list.length===1?'BOOK':'BOOKS'}</strong><span style="flex:1"></span><button class="secondary" id="sortAZ" ${list.length?'':'disabled'}>A–Z</button><button class="secondary" id="randomize" ${list.length?'':'disabled'}>Randomize</button><button class="secondary" id="resetOrder" ${list.length?'':'disabled'}>Undo changes</button></div><div class="warning">Changes are kept while you switch pages. Pinned books stay in position when you sort or randomize.</div>${list.length?`<section class="catalog-grid" id="catalog">${list.map((b,i)=>catalogCard(b,i)).join('')}</section>`:`<div class="empty"><h3>No approved books on this page</h3><p>${escapeHtml(currentGroup?.label||'Approve a book first, then return here.')}</p></div>`}`;const groupSelect=document.querySelector('#arrangeGenre');if(groupSelect)groupSelect.onchange=e=>{rememberCurrentArrangement();arrangeGenre=e.target.value;renderArrange()};bindArrange(list,groupKeys);setTimeout(hydrateCovers,0)}
function catalogCard(b,i){return `<article class="catalog-card" draggable="true" data-id="${b.id}">${cover(b)}<span class="position">${i+1}</span><button class="pin ${b.pin?'active':''}" aria-label="Pin ${escapeHtml(b.title)}">◆</button><h3>${escapeHtml(b.title)}</h3><p>${escapeHtml(b.author)}</p></article>`}
function rememberCurrentArrangement(){const grid=document.querySelector('#catalog');if(grid)arrangeDrafts.set(arrangeGenre,getCatalogBooks(grid).map(b=>b.id))}
function bindArrange(list,groupKeys){const grid=document.querySelector('#catalog');if(!grid)return;let drag=null;const redraw=next=>{arrangeDrafts.set(arrangeGenre,next.map(b=>b.id));grid.innerHTML=next.map((b,i)=>catalogCard(b,i)).join('');bindArrange(next,groupKeys);setTimeout(hydrateCovers,0)},withPinnedPositions=(source,sorter)=>{const unpinned=source.filter(b=>!b.pin);sorter(unpinned);let n=0;return source.map(b=>b.pin?b:unpinned[n++])};grid.querySelectorAll('.catalog-card').forEach(card=>{card.ondragstart=()=>{drag=card;card.classList.add('dragging')};card.ondragend=()=>{card.classList.remove('dragging');renumber();rememberCurrentArrangement()};card.ondragover=e=>{e.preventDefault();if(drag!==card)grid.insertBefore(drag,card)};card.querySelector('.pin').onclick=()=>{const b=books.find(x=>x.id===card.dataset.id);b.pin=!b.pin;card.querySelector('.pin').classList.toggle('active',b.pin)}});document.querySelector('#randomize').onclick=()=>{const current=getCatalogBooks(grid);redraw(withPinnedPositions(current,items=>items.sort(()=>Math.random()-.5)));toast('Randomized preview — pinned positions preserved')};document.querySelector('#sortAZ').onclick=()=>{const current=getCatalogBooks(grid);redraw(withPinnedPositions(current,items=>items.sort((a,b)=>a.title.localeCompare(b.title))))};document.querySelector('#resetOrder').onclick=()=>{arrangeDrafts.delete(arrangeGenre);renderArrange()};document.querySelector('#saveOrder').onclick=()=>saveCatalogGenres([arrangeGenre],document.querySelector('#saveOrder'),'Save this page');document.querySelector('#saveAllOrder').onclick=()=>saveCatalogGenres(groupKeys,document.querySelector('#saveAllOrder'),'Save all pages')}
async function saveCatalogGenres(groupKeys,button,label){rememberCurrentArrangement();const groups=groupKeys.map(groupKey=>({groupKey,books:draftGenreBooks(groupKey)})),items=groups.flatMap(group=>group.books.map((b,index)=>({bookId:b.id,isPinned:b.pin,displayOrder:index+1})));button.disabled=true;button.textContent='Saving…';try{await apiRequest('saveCatalogOrder',{items});groups.forEach(group=>group.books.forEach((b,index)=>{b.order=index+1;b.recordVersion++}));toast(`${groupKeys.length===1?'Page':'All pages'} saved to Google and added to the audit log`)}catch(error){toast(error.message||'Could not save catalog order')}finally{button.disabled=false;button.textContent=label}}
function getCatalogBooks(grid){return [...grid.querySelectorAll('.catalog-card')].map(card=>books.find(b=>b.id===card.dataset.id)).filter(Boolean)}
function renumber(){document.querySelectorAll('.position').forEach((x,i)=>x.textContent=i+1)}
function publishEligibleBooks(){return books.filter(b=>b.status==='Approved'&&(['Not Published','Ready to publish','Catalog Refresh','Update Required','Update Required: Link','Update Required: Cover'].includes(b.publicationStatus)||!b.publicationStatus))}
async function createPublicationPacket(){const eligible=publishEligibleBooks(),coverBooks=eligible.filter(b=>b.publicationStatus!=='Catalog Refresh'&&b.publicationStatus!=='Update Required: Link');const missing=coverBooks.filter(b=>!b.coverFileId),brokenLinks=eligible.filter(b=>!/^https?:\/\//i.test(b.url));if(missing.length||brokenLinks.length){toast(`Packet blocked: ${missing.length} missing cover${missing.length===1?'':'s'}, ${brokenLinks.length} invalid link${brokenLinks.length===1?'':'s'}`);return}const button=document.querySelector('#createPacket'),status=document.querySelector('#packetStatus');button.disabled=true;let downloaded=false;try{const files=[],total=coverBooks.length;let completed=0;status.textContent=`Preparing 0 of ${total} covers…`;const covers=await mapLimit(coverBooks,4,async b=>{const result=await apiRequest('getCover',{fileId:b.coverFileId});const data=await optimizeCover(result.dataUrl);completed++;status.textContent=`Preparing ${completed} of ${total} covers…`;return {name:`covers/${b.id}.webp`,data}});files.push(...covers);const headers=['book_id','title','author','genre','event_type','destination_type','destination_url','display_order','publication_status','cover_filename','requires_cover_upload'];const rows=eligible.map(b=>[b.id,b.title,b.author,b.genre,b.sourceType,b.destination,b.url,b.order,b.publicationStatus,coverBooks.includes(b)?`${b.id}.webp`:'',coverBooks.includes(b)?'Yes':'No']);files.push({name:'BRAE-publication-manifest.csv',data:new TextEncoder().encode('\ufeff'+[headers,...rows].map(row=>row.map(csvCell).join(',')).join('\r\n'))});files.push({name:'READ-ME-FIRST.txt',data:new TextEncoder().encode('BRAE PUBLICATION PACKET\r\n\r\n1. Keep every cover filename unchanged.\r\n2. Bulk-upload the covers folder to the reusable unlinked Squarespace page.\r\n3. Return to the Review Hub and continue with URL collection.\r\n\r\nCatalog Refresh and link-only records appear in the manifest without duplicate cover files.\r\n')});const zip=makeZip(files),stamp=new Date().toISOString().replace(/\D/g,'').slice(0,14),filename=`BRAE-publication-packet-${stamp}.zip`;downloadBlob(zip,filename);downloaded=true;await apiRequest('markPacketCreated',{bookIds:eligible.map(b=>b.id),filename});eligible.forEach(b=>{b.publicationStatus=b.publicationStatus==='Catalog Refresh'||b.publicationStatus==='Update Required: Link'?'Ready for Catalog':'Packet Created: Cover';b.recordVersion++});toast(`Publication packet created with ${eligible.length} records`);renderPublish()}catch(error){toast(downloaded?'The ZIP downloaded, but Google did not mark it as packeted. Do not create another packet yet.':error.message||'The publication packet could not be created');button.disabled=false;status.textContent=downloaded?'Packet downloaded, but its Google status was not saved.':'Packet creation failed. Fix the problem and try again.'}}
async function mapLimit(items,limit,worker){const results=new Array(items.length);let next=0;async function run(){while(next<items.length){const index=next++;results[index]=await worker(items[index],index)}}await Promise.all(Array.from({length:Math.min(limit,items.length)},run));return results}
async function optimizeCover(dataUrl){const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('A cover image could not be opened.'));img.src=dataUrl});const scale=Math.min(1,900/image.width),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.82));if(!blob)throw new Error('A cover could not be converted to WebP.');return new Uint8Array(await blob.arrayBuffer())}
function csvCell(value){const text=String(value??'');return /[",\r\n]/.test(text)?`"${text.replaceAll('"','""')}"`:text}
function crc32(bytes){let crc=-1;for(const byte of bytes){crc^=byte;for(let i=0;i<8;i++)crc=(crc>>>1)^((crc&1)?0xedb88320:0)}return (crc^-1)>>>0}
function zipPart(size,writer){const bytes=new Uint8Array(size),view=new DataView(bytes.buffer);writer(view,bytes);return bytes}
function makeZip(files){const encoder=new TextEncoder(),parts=[],central=[];let offset=0;for(const file of files){const name=encoder.encode(file.name),data=file.data instanceof Uint8Array?file.data:new Uint8Array(file.data),crc=crc32(data),local=zipPart(30+name.length,(v,b)=>{v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x0800,true);v.setUint16(8,0,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);b.set(name,30)});parts.push(local,data);const entryOffset=offset;offset+=local.length+data.length;central.push(zipPart(46+name.length,(v,b)=>{v.setUint32(0,0x02014b50,true);v.setUint16(4,20,true);v.setUint16(6,20,true);v.setUint16(8,0x0800,true);v.setUint16(10,0,true);v.setUint32(16,crc,true);v.setUint32(20,data.length,true);v.setUint32(24,data.length,true);v.setUint16(28,name.length,true);v.setUint32(42,entryOffset,true);b.set(name,46)}))}const centralSize=central.reduce((sum,x)=>sum+x.length,0),end=zipPart(22,v=>{v.setUint32(0,0x06054b50,true);v.setUint16(8,files.length,true);v.setUint16(10,files.length,true);v.setUint32(12,centralSize,true);v.setUint32(16,offset,true)});return new Blob([...parts,...central,end],{type:'application/zip'})}
function downloadBlob(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function urlImporterHtml(packeted){const waiting=packeted.length;return `<div class="url-importer"><p>Save this shortcut once, then use it from the public temporary-cover page whenever a packet is uploaded.</p><a class="secondary collector-link" id="collectorBookmark">Book URL Collector</a>${waiting?`<label>Paste collected Squarespace image URLs<textarea class="field" id="squarespaceUrls" rows="6" placeholder="Paste the URLs copied by Book URL Collector"></textarea></label><button class="secondary wide" id="matchUrls">Match and save book URLs</button><small id="matchStatus">${waiting} cover${waiting===1?' is':'s are'} waiting to be matched.</small>`:'<small>No uploaded covers are waiting to be matched right now.</small>'}</div>`}
function collectorBookmarklet(){return `javascript:(()=>{const u=[...new Set([...document.images].flatMap(i=>[i.currentSrc,i.src,i.getAttribute('data-src'),...(i.srcset||'').split(',').map(s=>s.trim().split(/\\s+/)[0])]).filter(x=>x&&x.includes('images.squarespace-cdn.com')).map(x=>x.replace(/&amp;/g,'&').split('?')[0]+'?format=1000w'))],t=u.join('\\n');if(!u.length){alert('BRAE: No Squarespace cover images found.');return}navigator.clipboard.writeText(t).then(()=>alert('BRAE: '+u.length+' Squarespace image URLs copied.'),()=>prompt('Copy these Squarespace image URLs:',t));})()`}
function bindUrlImporter(packeted){const bookmark=document.querySelector('#collectorBookmark'),button=document.querySelector('#matchUrls');if(!bookmark)return;bookmark.href=collectorBookmarklet();bookmark.onclick=event=>{event.preventDefault();toast('Drag Book URL Collector to your bookmarks bar—do not click it here.')};if(button)button.onclick=()=>matchSquarespaceUrls(packeted)}
async function matchSquarespaceUrls(packeted){const field=document.querySelector('#squarespaceUrls'),status=document.querySelector('#matchStatus'),button=document.querySelector('#matchUrls'),normalize=url=>String(url||'').replace(/&amp;/g,'&').split('?')[0],found=field.value.match(/https:\/\/images\.squarespace-cdn\.com\/[^\s"'<>]+/gi)||[],urls=[...new Set(found.map(url=>normalize(url)+'?format=1000w'))],matches=[],missing=[],duplicates=[];packeted.forEach(book=>{const id=book.id.toLowerCase(),oldBase=normalize(book.squarespaceCoverUrl),candidates=urls.filter(url=>{try{return decodeURIComponent(url).toLowerCase().includes(id)}catch(error){return url.toLowerCase().includes(id)}}),newCandidates=candidates.filter(url=>normalize(url)!==oldBase);if(newCandidates.length===1)matches.push({bookId:book.id,url:newCandidates[0]});else if(newCandidates.length>1)duplicates.push(book.id);else if(oldBase&&candidates.some(url=>normalize(url)===oldBase))matches.push({bookId:book.id,url:book.squarespaceCoverUrl});else missing.push(book.id)});if(missing.length||duplicates.length){status.textContent=`Not saved: ${missing.length} missing and ${duplicates.length} ambiguous matches.`;toast('URL matching is incomplete. Nothing was saved.');return}button.disabled=true;button.textContent='Saving matches…';try{await apiRequest('importSquarespaceUrls',{matches});matches.forEach(match=>{const book=books.find(b=>b.id===match.bookId);book.squarespaceCoverUrl=match.url;book.publicationStatus='Ready for Catalog';book.recordVersion++});toast(`${matches.length} Squarespace cover URLs matched and saved`);renderPublish()}catch(error){toast(error.message||'Squarespace URLs were not saved');button.disabled=false;button.textContent='Match and save URLs'}}
function renderAudit(){view.innerHTML=`<div class="page-head"><div><p class="eyebrow">ACCOUNTABILITY</p><h1>Audit Log</h1><p>A permanent record of review, editing, ordering, and publication actions.</p></div><button class="secondary">Export log</button></div><div class="toolbar"><input class="field search" placeholder="Search user, book, author or action"><select class="field"><option>All actions</option><option>Approved</option><option>Needs Info</option><option>Denied</option><option>Edited</option></select><input class="field" type="date" aria-label="Start date"><input class="field" type="date" aria-label="End date"></div><div class="table-wrap"><table class="table"><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Record</th><th>Details</th></tr></thead><tbody>${audit.concat([['2 hr ago','Maria Chen','claimed review','A Crown of Salt'],['Yesterday','Kim Foster','moved catalog position','BRAE-2026-00152'],['Yesterday','Denise Williams','reassigned reviewer','River of Glass']]).map(a=>`<tr><td>${a[0]}</td><td><strong>${a[1]}</strong></td><td>${a[2]}</td><td>${a[3]}</td><td><button class="link-btn">View changes</button></td></tr>`).join('')}</tbody></table></div>`}
function renderAdmin(){view.innerHTML=`<div class="page-head"><div><p class="eyebrow">SYSTEM CONTROL</p><h1>Admin & Settings</h1><p>Manage event configuration, access, genres, and publishing permissions.</p></div><button class="primary">Invite user</button></div><section class="dashboard-grid"><article class="panel"><div class="panel-head"><h2>Team access</h2><span class="badge">5 active</span></div>${[['Denise Williams','Super Admin'],['Maria Chen','Admin'],['Andre Lewis','Reviewer'],['Kim Foster','Reviewer'],['Jordan Price','Reviewer']].map((u,i)=>`<div class="activity"><li><span class="avatar">${u[0].split(' ').map(x=>x[0]).join('')}</span><span><strong>${u[0]}</strong><small class="muted" style="display:block">${u[1]} · ${i?'Active today':'You'}</small></span><button class="secondary">Manage</button></li></div>`).join('')}</article><div><article class="panel"><div class="panel-head"><h2>Event settings</h2><button class="link-btn">Edit</button></div><ul class="meta-list"><li><span>Event year</span><strong>2026</strong></li><li><span>Max books / author</span><strong>3</strong></li><li><span>Auto-advance</span><strong>Enabled</strong></li><li><span>Mock API mode</span><strong>On</strong></li></ul></article><article class="panel" style="margin-top:18px"><div class="panel-head"><h2>Genres</h2><button class="link-btn">Manage</button></div>${genres.map((g,i)=>`<div class="genre-row"><strong>${i+1}. ${g}</strong><span class="muted">Active</span><button class="link-btn">Edit</button></div>`).join('')}</article></div></section>`}
function bindGo(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{route=b.dataset.go;render()});document.querySelectorAll('[data-next]').forEach(b=>b.onclick=()=>openBook(books.find(x=>x.status==='Pending')))}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}

function renderPublish(){const approved=books.filter(b=>b.status==='Approved'),published=approved.filter(b=>b.publicationStatus==='Published'),readyCatalog=approved.filter(b=>b.publicationStatus==='Ready for Catalog'),packeted=approved.filter(b=>b.publicationStatus.startsWith('Packet Created')),eligible=publishEligibleBooks();view.innerHTML=`<div class="page-head"><div><p class="eyebrow">SQUARESPACE CATALOG RELEASE</p><h1>Publish Catalog</h1><p>Four steps. Complete them in order for each publication batch.</p></div><span class="status updated">${eligible.length+packeted.length+readyCatalog.length} in progress</span></div>${publishNotice?`<div class="publish-success" role="status">${escapeHtml(publishNotice)}</div>`:''}<section class="publish-status-strip"><span><strong>${eligible.length}</strong> ready for packet</span><span><strong>${packeted.length}</strong> waiting for URLs</span><span><strong>${readyCatalog.length}</strong> ready for Squarespace</span><span><strong>${published.length}</strong> published</span></section><details class="panel squarespace-setup"><summary>One-time Squarespace catalog setup</summary>${catalogSetupHtml()}</details><section class="publish-compact"><article class="panel publish-action-card"><div class="compact-step-head"><span class="step-number">1</span><div><h2>Create and upload the publication packet</h2><p>Click <strong>Create Publication Packet</strong>, upload its images to Squarespace <strong>Temp Cover Uploads</strong>, and save the page.</p></div></div><div class="step-control"><div class="warning" id="packetStatus">${eligible.length?'The next packet will contain only new or changed records.':'There are no new or changed records waiting for a packet.'}</div><button class="primary" id="createPacket" ${eligible.length&&currentUser?.can_publish?'':'disabled'}>Create Publication Packet</button></div><details class="publish-help"><summary>Show how to upload covers</summary><ol><li>Download and unzip the publication packet.</li><li>Open <strong>Pages → Not Linked → Temp Cover Uploads</strong> in Squarespace.</li><li>Edit the gallery and upload every image from the packet’s <strong>covers</strong> folder.</li><li>Keep all filenames unchanged, wait for every upload to finish, then save.</li></ol><div class="publish-guide"><figure><img src="assets/publish-help/step1-01-pages.png" alt="Squarespace Website menu with Pages circled"><figcaption>1. Open Pages.</figcaption></figure><figure><img src="assets/publish-help/step1-02-temp-cover-uploads.png" alt="Temp Cover Uploads page and Edit button circled"><figcaption>2. Select Temp Cover Uploads and click Edit.</figcaption></figure><figure><img src="assets/publish-help/step1-03-edit-gallery.png" alt="Edit Gallery button circled"><figcaption>3. Click Edit Gallery.</figcaption></figure><figure><img src="assets/publish-help/step1-04-upload-images.png" alt="Upload Images option circled"><figcaption>4. Click plus, then Upload Images.</figcaption></figure></div></details></article><article class="panel publish-action-card"><div class="compact-step-head"><span class="step-number">2</span><div><h2>Collect and match the cover URLs</h2><p>Add <strong>Book URL Collector</strong> to the bookmarks bar once. Open <a href="https://www.brae.website/temp-cover-uploads" target="_blank" rel="noopener">Temp Cover Uploads ↗</a>, click the shortcut, then paste the copied URLs below.</p></div></div>${urlImporterHtml(packeted)}</article><article class="panel publish-action-card"><div class="compact-step-head"><span class="step-number">3</span><div><h2>Update the changed Squarespace data pages</h2><p>Generate the changed pages, then replace every numbered data block on each listed hidden Squarespace page.</p></div></div>${catalogPublisherHtml(readyCatalog,published)}</article><article class="panel publish-action-card"><div class="compact-step-head"><span class="step-number">4</span><div><h2>Confirm the catalog update</h2><p>Only confirm after every affected public catalog page has been checked.</p></div></div>${catalogConfirmationHtml()}</article></section>`;const button=document.querySelector('#createPacket');if(button)button.onclick=createPublicationPacket;bindUrlImporter(packeted);bindCatalogPublisher(readyCatalog,published);bindCatalogSetup()}

function catalogPublisherHtml(readyCatalog,published){if(!readyCatalog.length&&!catalogDraft)return `<div class="step-control muted">No batch is Ready for Squarespace yet.</div>`;const page=catalogDraft?.pages[catalogDraft.selectedIndex||0],block=page?.blocks[catalogDraft.blockIndex||0];return `<div class="catalog-publisher"><div class="catalog-actions"><button class="primary" id="generateCatalog" ${currentUser?.can_publish?'':'disabled'}>Generate changed pages</button>${catalogDraft?'<button class="secondary" id="copyCatalog">Copy selected block</button><button class="secondary" id="downloadBlock">Download selected .txt</button><button class="secondary" id="downloadCatalog">Download all .txt files</button>':''}</div>${catalogDraft?`<label class="catalog-code-label">Affected catalog page<select class="field catalog-page-select" id="catalogSnippet">${catalogDraft.pages.map((item,index)=>`<option value="${index}" ${index===catalogDraft.selectedIndex?'selected':''}>${escapeHtml(item.label)} · ${item.count} book${item.count===1?'':'s'}</option>`).join('')}</select></label><div class="catalog-page-note"><strong>Hidden data page:</strong> ${escapeHtml(page.dataPath)}<br><strong>Visible cover sections needed:</strong> ${page.slotCount} (${page.count} books, up to 50 per section)</div><label class="catalog-code-label">Numbered data block<select class="field catalog-page-select" id="catalogBlock">${page.blocks.map((item,index)=>`<option value="${index}" ${index===(catalogDraft.blockIndex||0)?'selected':''}>Block ${index+1} of ${page.blocks.length}</option>`).join('')}</select><textarea class="field catalog-code" id="catalogCode" rows="10" readonly>${escapeHtml(block.code)}</textarea></label><div class="warning">Replace every block on all ${catalogDraft.pages.length} listed hidden data page${catalogDraft.pages.length===1?'':'s'}, then verify the corresponding public pages.</div>`:`<p class="muted">${readyCatalog.length} record${readyCatalog.length===1?' is':'s are'} ready. Only affected pages will be generated, and each will contain its complete current catalog.</p>`}<details class="publish-help"><summary>Show how to update catalog data</summary><ol><li>Choose an affected page and note its hidden data-page address.</li><li>Replace that hidden page’s existing code blocks with all numbered blocks shown here.</li><li>Use <strong>Download all .txt files</strong> if copying from plain text is easier.</li><li>Save the hidden page and verify the matching public catalog page. The public page fills its 50-book sections automatically.</li></ol><div class="guide-media-slot"><strong>Visual guide</strong><span>A screenshot sequence or short screen recording can be added here later.</span></div></details></div>`}

function catalogConfirmationHtml(){if(!catalogDraft)return '<p class="muted">Generate the changed pages in Step 3 before confirming publication.</p><button class="primary wide" disabled>Confirm catalog published</button>';return `<label class="publish-confirm"><input type="checkbox" id="catalogVerified"> I updated the Squarespace data and verified every affected catalog page</label><button class="primary wide" id="confirmCatalog" disabled>Confirm catalog published</button><small class="muted">This marks the ${catalogDraft.readyIds.length} current Ready for Catalog record${catalogDraft.readyIds.length===1?'':'s'} as Published.</small>`}
function bindCatalogPublisher(readyCatalog,published){const generate=document.querySelector('#generateCatalog');if(generate)generate.onclick=()=>{try{catalogDraft=buildCatalogDraft(readyCatalog,published);publishNotice=`${catalogDraft.pages.length} changed catalog page${catalogDraft.pages.length===1?' was':'s were'} generated. Each contains its complete current book list. Nothing has been marked Published.`;renderPublish()}catch(error){toast(error.message)}};if(!catalogDraft)return;const renderSelection=()=>renderPublish(),select=document.querySelector('#catalogSnippet'),blockSelect=document.querySelector('#catalogBlock'),copy=document.querySelector('#copyCatalog'),downloadBlock=document.querySelector('#downloadBlock'),download=document.querySelector('#downloadCatalog'),verified=document.querySelector('#catalogVerified'),confirm=document.querySelector('#confirmCatalog');if(select)select.onchange=()=>{catalogDraft.selectedIndex=Number(select.value);catalogDraft.blockIndex=0;renderSelection()};if(blockSelect)blockSelect.onchange=()=>{catalogDraft.blockIndex=Number(blockSelect.value);document.querySelector('#catalogCode').value=catalogDraft.pages[catalogDraft.selectedIndex].blocks[catalogDraft.blockIndex].code};if(copy)copy.onclick=async()=>{const page=catalogDraft.pages[catalogDraft.selectedIndex||0],block=page.blocks[catalogDraft.blockIndex||0];try{await navigator.clipboard.writeText(block.code);toast(`${page.label} block ${block.index} copied`)}catch(error){document.querySelector('#catalogCode').select();toast('Clipboard access was blocked. The code is selected for copying.')}};if(downloadBlock)downloadBlock.onclick=()=>{const page=catalogDraft.pages[catalogDraft.selectedIndex||0],block=page.blocks[catalogDraft.blockIndex||0];downloadBlob(new Blob([block.code],{type:'text/plain;charset=utf-8'}),block.filename)};if(download)download.onclick=()=>{const files=catalogDraft.pages.flatMap(page=>page.blocks.map(block=>({name:`${page.slug}/${block.filename}`,data:new TextEncoder().encode(block.code)})));files.push({name:'READ-ME.txt',data:new TextEncoder().encode('BRAE SQUARESPACE CATALOG DATA\r\n\r\nOnly changed pages are included. For each folder, replace every code block on the matching hidden Squarespace data page. Files are numbered in the required order. Each block contains up to 50 books.\r\n')});downloadBlob(makeZip(files),`BRAE-Squarespace-data-${catalogDraft.version}.zip`)};if(verified)verified.onchange=()=>confirm.disabled=!verified.checked;if(confirm)confirm.onclick=confirmCatalogPublished}

function slugify(value){return String(value||'other').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function catalogPageForBook(book){if(book.sourceType==='AUDIOBOOK')return {key:'audiobooks',label:'Audiobooks',slug:'audiobooks'};if(book.sourceType==='ONE_DAY_EBOOK')return {key:'one-day-ebooks',label:'One-Day Free Books',slug:'one-day-ebooks'};const genre=book.genre||'Other',slug=slugify(genre);return {key:`genre--${slug}`,label:genre,slug}}
function catalogPageDefinitions(){const definitions=[{key:'audiobooks',label:'Audiobooks',slug:'audiobooks'},{key:'one-day-ebooks',label:'One-Day Free Books',slug:'one-day-ebooks'},...genres.map(genre=>({key:`genre--${slugify(genre)}`,label:genre,slug:slugify(genre)}))],seen=new Set();return definitions.filter(page=>!seen.has(page.key)&&seen.add(page.key))}
function buildCatalogDraft(readyCatalog,published){
  const seen=new Set();
  const catalogBooks=[...published,...readyCatalog].filter(book=>{
    if(seen.has(book.id))return false;
    seen.add(book.id);
    return true;
  });
  const invalid=catalogBooks.filter(book=>!/^https:\/\/images\.squarespace-cdn\.com\//i.test(book.squarespaceCoverUrl)||!/^https?:\/\//i.test(book.url));
  if(invalid.length)throw new Error(`Catalog blocked: ${invalid.length} book${invalid.length===1?' has':'s have'} a missing cover or invalid destination link.`);
  const affected=new Set();
  readyCatalog.forEach(book=>{
    affected.add(catalogPageForBook(book).key);
    if(book.publishedPageKey)affected.add(book.publishedPageKey);
  });
  const definitions=new Map(catalogPageDefinitions().map(page=>[page.key,page]));
  catalogBooks.forEach(book=>{
    const page=catalogPageForBook(book);
    if(!definitions.has(page.key))definitions.set(page.key,page);
  });
  const pages=[...affected].map(key=>definitions.get(key)||{key,label:key,slug:slugify(key)}).map(page=>{
    const list=catalogBooks.filter(book=>catalogPageForBook(book).key===page.key).sort((a,b)=>Number(b.pin)-Number(a.pin)||(a.order||999999)-(b.order||999999)||a.title.localeCompare(b.title));
    const chunks=[];
    for(let i=0;i<list.length;i+=50)chunks.push(list.slice(i,i+50));
    if(!chunks.length)chunks.push([]);
    const blocks=chunks.map((chunk,index)=>{
      const payload=chunk.map(book=>({id:book.id,t:book.title,a:book.author,u:book.url,c:book.squarespaceCoverUrl}));
      const safeJson=JSON.stringify(payload).replaceAll('</','<\\/');
      const code=`<script type="application/json" data-brae-catalog="${page.key}" data-brae-part="${index+1}">${safeJson}</script>`;
      const filename=`${page.slug}--block-${String(index+1).padStart(2,'0')}.txt`;
      return {index:index+1,code,filename,count:chunk.length};
    });
    return {...page,dataPath:`/brae-data-${page.slug}`,count:list.length,slotCount:Math.max(1,Math.ceil(list.length/50)),blocks};
  });
  return {pages,selectedIndex:0,blockIndex:0,total:catalogBooks.length,readyIds:readyCatalog.map(book=>book.id),pageAssignments:Object.fromEntries(readyCatalog.map(book=>[book.id,catalogPageForBook(book).key])),version:new Date().toISOString().replace(/\D/g,'').slice(0,14)};
}

function catalogSetupHtml(){const pages=catalogPageDefinitions(),selected=pages[0];return `<div class="setup-body"><p>Do this once for each catalog page. The public page will then read its books from a hidden Squarespace data page; routine publishing never requires editing the public page code.</p><label>Catalog page<select class="field catalog-page-select" id="setupPage">${pages.map((page,index)=>`<option value="${index}">${escapeHtml(page.label)}</option>`).join('')}</select></label><div class="catalog-page-note" id="setupPath"><strong>Hidden data page:</strong> /brae-data-${selected.slug}</div><div class="catalog-actions"><button class="secondary" id="copyLoader">Copy one-time loader</button><button class="secondary" id="downloadLoader">Download loader .txt</button><button class="secondary" id="copySlot">Copy 50-book section</button><button class="secondary" id="downloadSlot">Download section .txt</button></div><ol><li>Create the listed hidden page under <strong>Not Linked</strong>.</li><li>Add the loader code once to the matching public catalog page.</li><li>Add a separate code section containing the 50-book section code. Duplicate that section for each group of 50 books.</li><li>Place an ordinary Squarespace ad section between those book sections. Extra empty book sections hide automatically.</li></ol></div>`}
function catalogLoaderCode(page){return `<script>(()=>{const K=${JSON.stringify(page.key)},U=${JSON.stringify(`/brae-data-${page.slug}`)};function esc(v){return String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function draw(){fetch(U,{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Catalog data unavailable');return r.text()}).then(html=>{const doc=new DOMParser().parseFromString(html,'text/html'),parts=[...doc.querySelectorAll('script[data-brae-catalog="'+K+'"]')].sort((a,b)=>Number(a.dataset.braePart)-Number(b.dataset.braePart)),books=parts.flatMap(node=>{try{return JSON.parse(node.textContent)}catch(e){return[]}}),slots=[...document.querySelectorAll('.brae-catalog-slot[data-brae-page="'+K+'"]')];slots.forEach((slot,index)=>{const list=books.slice(index*50,index*50+50);slot.hidden=!list.length;slot.innerHTML=list.map(b=>'<a class="brae-book" href="'+esc(b.u)+'" target="_blank" rel="noopener noreferrer" aria-label="Open '+esc(b.t)+' by '+esc(b.a)+'"><img src="'+esc(b.c)+'" alt="'+esc(b.t)+' by '+esc(b.a)+'" loading="lazy" decoding="async"></a>').join('')})}).catch(error=>console.error('BRAE catalog:',error))}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',draw):draw()})();</script><style>.brae-catalog-slot{--brae-gap:clamp(1rem,2.2vw,1.8rem);display:flex;flex-wrap:wrap;justify-content:center;align-items:flex-start;gap:var(--brae-gap);width:100%;height:auto}.brae-book{display:block;box-sizing:border-box;flex:0 1 calc((100% - (4 * var(--brae-gap)))/5);min-width:0;border-radius:12px;outline:none;text-decoration:none;transition:transform .24s ease,filter .24s ease}.brae-book img{display:block;width:100%;height:auto;aspect-ratio:2/3;object-fit:cover;border-radius:12px;background:#eee;box-shadow:0 14px 28px rgba(25,14,10,.24),0 4px 10px rgba(25,14,10,.14);transition:box-shadow .24s ease}.brae-book:hover,.brae-book:focus-visible{transform:translateY(-7px) scale(1.025);filter:saturate(1.04)}.brae-book:hover img,.brae-book:focus-visible img{box-shadow:0 22px 42px rgba(25,14,10,.30),0 7px 16px rgba(25,14,10,.17)}@media(max-width:900px){.brae-book{flex-basis:calc((100% - (3 * var(--brae-gap)))/4)}}@media(max-width:700px){.brae-catalog-slot{--brae-gap:.9rem}.brae-book{flex-basis:calc((100% - (2 * var(--brae-gap)))/3)}}@media(max-width:430px){.brae-book{flex-basis:calc((100% - var(--brae-gap))/2)}.brae-book,.brae-book img{border-radius:8px}}@media(prefers-reduced-motion:reduce){.brae-book,.brae-book img{transition:none}.brae-book:hover,.brae-book:focus-visible{transform:none}}</style>`}
function catalogSlotCode(page){return `<div class="brae-catalog-slot" data-brae-page="${page.key}" aria-live="polite"></div>`}
function bindCatalogSetup(){const select=document.querySelector('#setupPage');if(!select)return;const pages=catalogPageDefinitions(),current=()=>pages[Number(select.value)||0],saveText=(text,name)=>downloadBlob(new Blob([text],{type:'text/plain;charset=utf-8'}),name),copy=async(text,label)=>{try{await navigator.clipboard.writeText(text);toast(`${label} copied`)}catch(error){toast('Clipboard access was blocked. Use the .txt download instead.')}};select.onchange=()=>{document.querySelector('#setupPath').innerHTML=`<strong>Hidden data page:</strong> /brae-data-${current().slug}`};document.querySelector('#copyLoader').onclick=()=>copy(catalogLoaderCode(current()),`${current().label} loader`);document.querySelector('#downloadLoader').onclick=()=>saveText(catalogLoaderCode(current()),`${current().slug}--one-time-loader.txt`);document.querySelector('#copySlot').onclick=()=>copy(catalogSlotCode(current()),`${current().label} section`);document.querySelector('#downloadSlot').onclick=()=>saveText(catalogSlotCode(current()),`${current().slug}--50-book-section.txt`)}

async function confirmCatalogPublished(){if(!catalogDraft?.readyIds.length){toast('There is no Ready for Catalog batch to publish');return}const button=document.querySelector('#confirmCatalog');button.disabled=true;button.textContent='Recording publication…';try{const result=await apiRequest('markCatalogPublished',{bookIds:catalogDraft.readyIds,pageAssignments:catalogDraft.pageAssignments,catalogVersion:catalogDraft.version,totalBooks:catalogDraft.total}),readySet=new Set(catalogDraft.readyIds);books.forEach(book=>{if(readySet.has(book.id)){book.publicationStatus='Published';book.published=true;book.publishedPageKey=catalogDraft.pageAssignments[book.id]||book.publishedPageKey;book.recordVersion++}});metrics.published=books.filter(b=>b.status==='Approved'&&b.publicationStatus==='Published').length;publishNotice=`Catalog ${result.catalogVersion||catalogDraft.version} was confirmed. ${catalogDraft.readyIds.length} record${catalogDraft.readyIds.length===1?' is':'s are'} now Published.`;catalogDraft=null;toast('Catalog publication recorded in Google');renderPublish()}catch(error){toast(error.message||'Publication was not recorded');button.disabled=false;button.textContent='Confirm catalog published'}}
